6	/**
7	 * wouter location hook that runs every push inside a View Transition.
8	 *
9	 * Drop-in for the default browser-location hook via `<Router hook={useVTLocation}>`,
10	 * so the 20+ existing `setLocation` call sites get a native crossfade for free
11	 * with no per-call edits. Page-pairs that share a named element morph
12	 * automatically (the browser animates the matching `view-transition-name`s).
13	 *
14	 * Crossfade by default (`expectReady: false`); the property orchestrator opts
15	 * its own navigations into the freeze-until-ready morph and is protected from
16	 * double-wrapping by the re-entrancy guard in navigateVT.
17	 */
18	export const useVTLocation = (): [string, (to: string, opts?: NavOpts) => void] => {
19	  const [path, navigate] = useBrowserLocation();
20	  const vtNavigate = (to: string, opts?: NavOpts) =>
21	    navigateVT(() => navigate(to, opts), { expectReady: false });
22	  return [path, vtNavigate];
23	};
