type NavOpts = { replace?: boolean; state?: any };

/**
 * wouter location hook that runs every push inside a View Transition.
 *
 * Drop-in for the default browser-location hook via `<Router hook={useVTLocation}>`,
 * so the 20+ existing `setLocation` call sites get a native crossfade for free
 * with no per-call edits. Page-pairs that share a named element morph
 * automatically (the browser animates the matching `view-transition-name`s).
 *
 * Crossfade by default (`expectReady: false`); the property orchestrator opts
 * its own navigations into the freeze-until-ready morph and is protected from
 * double-wrapping by the re-entrancy guard in navigateVT.
 */
export const useVTLocation = (): [string, (to: string, opts?: NavOpts) => void] => {
  const [path, navigate] = useBrowserLocation();
  const vtNavigate = (to: string, opts?: NavOpts) =>
    navigateVT(() => navigate(to, opts), { expectReady: false });
  return [path, vtNavigate];
};

