/**
 * Generic View-Transition engine.
 *
 * Runs a navigation inside the browser's View Transitions API when available,
 * holding the OLD frame until the destination page mounts its morph targets
 * (it calls `signalReady()` from a layout effect) — then lets the browser
 * capture the new snapshot so shared elements morph instead of crossfading.
 * Falls back to a plain navigation (no animation) on unsupported browsers.
 *
 * Module-level state (not React) so it survives route changes cleanly. This is
 * the single source of truth for VT state; property-transition.ts builds on it.
 */

let _pending = false;
let _readyResolve: (() => void) | null = null;

export const supportsVT = (): boolean =>
  typeof document !== "undefined" && "startViewTransition" in document;

export const isVTPending = (): boolean => _pending;

/** Destination pages call this from a layout effect once their morph targets are mounted. */
export function signalReady(): void {
  _readyResolve?.();
}

/**
 * Resolve once the destination route has mounted (it calls signalReady from a
 * layout effect), plus one frame so morph targets are laid out before the
 * browser captures. A timeout guards a destination that never signals so we
 * never hang.
 */
function waitForReady(timeoutMs = 1500): Promise<void> {
  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      _readyResolve = null;
      resolve();
    };
    // Settle one extra frame after the ready signal so layout is committed.
    _readyResolve = () => requestAnimationFrame(finish);
    setTimeout(finish, timeoutMs);
  });
}

/**
 * Run `go` (the actual navigation) inside a View Transition, holding the old
 * frame until the destination mounts. `expectReady=false` skips the wait for
 * targets with no morph element (immediate crossfade).
 */
export function navigateVT(go: () => void, opts?: { expectReady?: boolean }): void {
  // Re-entrancy guard: if a View Transition is already in flight (e.g. the
  // property orchestrator started one and its navigation flows back through the
  // global wrapper), just navigate directly instead of nesting transitions.
  if (!supportsVT() || _pending) { go(); return; }
  _pending = true;
  const vt = (document as any).startViewTransition(async () => {
    go();
    if (opts?.expectReady !== false) await waitForReady();
  });
  vt.finished.finally(() => { _pending = false; });
}

